WITH sales_per_customer AS (SELECT ss_customer_sk AS customer_sk, SUM(ss_net_paid_inc_tax) AS total_net_paid, SUM(ss_net_profit) AS total_net_profit, COUNT(*) AS sales_transactions FROM store_sales GROUP BY ss_customer_sk), returns_per_customer AS (SELECT wr_refunded_customer_sk AS customer_sk, SUM(wr_return_amt_inc_tax) AS total_return_amount, SUM(wr_net_loss) AS total_net_loss, COUNT(*) AS return_transactions FROM web_returns GROUP BY wr_refunded_customer_sk), customer_top_reason_agg AS (SELECT wr.wr_refunded_customer_sk AS customer_sk, wr.wr_reason_sk, COUNT(*) AS reason_cnt FROM web_returns wr GROUP BY wr.wr_refunded_customer_sk, wr.wr_reason_sk), customer_top_reason AS (SELECT customer_sk, wr_reason_sk, ROW_NUMBER() OVER (PARTITION BY customer_sk ORDER BY reason_cnt DESC) AS rn FROM customer_top_reason_agg) SELECT c.c_customer_id, c.c_first_name, c.c_last_name, c.c_birth_year, CASE WHEN c.c_birth_year >= 1997 THEN 'Gen Z' WHEN c.c_birth_year BETWEEN 1981 AND 1996 THEN 'Millennial' WHEN c.c_birth_year BETWEEN 1965 AND 1980 THEN 'Gen X' ELSE 'Boomer' END AS generation, COALESCE(s.total_net_paid, 0) AS total_net_paid, COALESCE(s.total_net_profit, 0) AS total_net_profit, COALESCE(r.total_return_amount, 0) AS total_return_amount, COALESCE(r.total_net_loss, 0) AS total_net_loss, CASE WHEN COALESCE(s.total_net_profit, 0) > 5000 THEN 'Platinum' WHEN COALESCE(s.total_net_profit, 0) > 1000 THEN 'Gold' WHEN COALESCE(s.total_net_profit, 0) > 0 THEN 'Silver' ELSE 'Bronze' END AS profit_tier, CASE WHEN COALESCE(r.total_return_amount, 0) > 0 THEN s.total_net_profit / NULLIF(r.total_return_amount, 0) ELSE NULL END AS profit_per_return, DENSE_RANK() OVER (ORDER BY CASE WHEN COALESCE(r.total_return_amount, 0) > 0 THEN s.total_net_profit / NULLIF(r.total_return_amount, 0) ELSE 0 END DESC) AS profit_return_rank, COALESCE(rt.r_reason_desc, 'No Returns') AS top_return_reason FROM customer c LEFT JOIN sales_per_customer s ON c.c_customer_sk = s.customer_sk LEFT JOIN returns_per_customer r ON c.c_customer_sk = r.customer_sk LEFT JOIN (SELECT customer_sk, wr_reason_sk FROM customer_top_reason WHERE rn = 1) tr ON c.c_customer_sk = tr.customer_sk LEFT JOIN reason rt ON tr.wr_reason_sk = rt.r_reason_sk WHERE c.c_birth_year IS NOT NULL ORDER BY profit_return_rank LIMIT 100
